// PostgREST returns one array; n8n's splitting behaviour has varied by version,
// so flatten defensively rather than assuming one item per row.
const rows = [];
for (const item of $input.all()) {
  const v = item.json;
  if (Array.isArray(v)) { rows.push(...v); } else if (v) { rows.push(v); }
}
return rows.filter(r => r && r.id).map(r => ({ json: r }));

const branch = $('Normalize Branches').item.json;
const res = $input.item.json || {};
let parsed = res.body;
if (typeof parsed === 'string') { try { parsed = JSON.parse(parsed); } catch (e) { parsed = null; } }

// A brand with no Meta credentials returns { connected: false }. That is a
// normal state, not a failure — emit nothing rather than writing a row of
// zeros, which would later read as "followers dropped to 0".
if (!parsed || parsed.connected === false) return [];

const today = new Date().toISOString().slice(0, 10);
const rows = [];
for (const platform of ['facebook', 'instagram']) {
  const stats = parsed[platform];
  if (!stats || stats.error) continue;
  // fans is Facebook's wording, followers is Instagram's.
  const followers = stats.followers ?? stats.fans ?? null;
  if (followers === null && stats.reach_28d == null) continue;
  rows.push({ json: {
    branch_id: branch.id,
    captured_on: today,
    platform,
    followers,
    posts: stats.posts ?? null,
    reach_28d: stats.reach_28d ?? null,
    raw: stats
  } });
}
return rows;
